import java.sql.*; public class TestDB { public static void main(String[] a) throws Exception { String[] pw = {"bereeze123","root","","admin","mysql"}; for (String p : pw) { try { Class.forName("com.mysql.cj.jdbc.Driver"); Connection c = DriverManager.getConnection("jdbc:mysql://localhost:3306/?allowPublicKeyRetrieval=true&useSSL=false","root",p); System.out.println("SUCCESS: " + p); ResultSet rs=c.createStatement().executeQuery("SHOW DATABASES"); while(rs.next()) System.out.println(" "+rs.getString(1)); c.close(); return; } catch (Exception e) { System.out.println("FAIL " + p + ": " + e.getMessage()); }}}}
